type State = { count: number };
type Action =
  | { type: 'increment'; payload?: number }
  | { type: 'decrement'; payload?: number }
  | { type: 'reset' };

function counterReducer(state: State, action: Action): State {
  switch (action.type) {
    case 'increment':
      return { count: state.count + (action.payload ?? 1) };
    case 'decrement':
      return { count: state.count - (action.payload ?? 1) };
    case 'reset':
      return { count: 0 };
    default:
      return state;
  }
}

function Counter() {
  const [state, dispatch] = useReducer(counterReducer, { count: 0 });

  return (
    <div className="flex items-center gap-4">
      <button onClick={() => dispatch({ type: 'decrement' })}>-</button>
      <span>{state.count}</span>
      <button onClick={() => dispatch({ type: 'increment', payload: 5 })}>+5</button>
      <button onClick={() => dispatch({ type: 'reset' })}>Reset</button>
    </div>
  );
}

type ToggleState = { on: boolean };

interface ToggleAction {
  type: 'TOGGLE' | 'SET' | 'RESET';
  payload?: { value: boolean };
}

function createToggleReducer(initial = false) {
  return function toggleReducer(state: ToggleState, action: ToggleAction): ToggleState {
    switch (action.type) {
      case 'TOGGLE':
        return { on: !state.on };
      case 'SET':
        return { on: action.payload!.value };
      case 'RESET':
        return { on: initial };
      default:
        return state;
    }
  };
}

function useToggle(initial = false) {
  const reducer = createToggleReducer(initial);
  const [state, dispatch] = useReducer(reducer, { on: initial });

  const toggle = () => dispatch({ type: 'TOGGLE' });
  const set = (value: boolean) => dispatch({ type: 'SET', payload: { value } });
  const reset = () => dispatch({ type: 'RESET' });

  return { ...state, toggle, set, reset };
}

// React Component Example with Hooks
import React, { useState, useEffect, useCallback } from 'react';

function DataFetcher({ endpoint }) {
  // State management with useState
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // useCallback for memoized fetch function
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // useEffect for side effects
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="data-container">
      <h2>Fetched Data</h2>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </div>
  );
}

export default DataFetcher;
